declare
  v_rows jsonb := $seed$[{"level":"SS1","category":null,"subject":"English Language","topic":"Tenses","question":"By the time the principal arrived, the assembly ___ for ten minutes.","option_a":"has begun","option_b":"had been going on","option_c":"will begin","option_d":"begins","correct_answer":"B","explanation":"The past perfect continuous describes an activity continuing up to another past event.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Reported speech","question":"Bola said, “I am revising for my test.” Which is the correct reported form?","option_a":"Bola said that I am revising for my test.","option_b":"Bola says that she was revising for her test.","option_c":"Bola said that she was revising for her test.","option_d":"Bola said that she is revising for my test.","correct_answer":"C","explanation":"In reported speech the pronoun changes to she and the present progressive usually shifts to the past progressive.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Question tags","question":"Choose the correct tag: “The candidates have submitted their forms, ___?”","option_a":"haven’t they","option_b":"didn’t they","option_c":"aren’t they","option_d":"don’t they","correct_answer":"A","explanation":"The auxiliary have is repeated in the negative tag, and candidates is represented by they.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Agreement","question":"Each of the players ___ a numbered jersey.","option_a":"wear","option_b":"wears","option_c":"were wearing","option_d":"have worn","correct_answer":"B","explanation":"Each is singular and takes a singular verb in the simple present.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Agreement","question":"The news from the examination centre ___ encouraging.","option_a":"are","option_b":"were","option_c":"have been","option_d":"is","correct_answer":"D","explanation":"News is an uncountable singular noun and takes is.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Prepositions","question":"The students congratulated Ada ___ winning the inter-school debate.","option_a":"for","option_b":"at","option_c":"on","option_d":"with","correct_answer":"C","explanation":"The usual collocation is congratulate someone on an achievement.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Prepositions","question":"The new science laboratory is adjacent ___ the library.","option_a":"to","option_b":"with","option_c":"at","option_d":"by","correct_answer":"A","explanation":"Adjacent is followed by the preposition to.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Word formation","question":"Which noun is formed from the verb “decide”?","option_a":"decisive","option_b":"decision","option_c":"decided","option_d":"decidingly","correct_answer":"B","explanation":"Decision is the noun derived from decide.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Word formation","question":"Which word is an adjective in “The careful driver avoided the pothole”?","option_a":"driver","option_b":"avoided","option_c":"pothole","option_d":"careful","correct_answer":"D","explanation":"Careful describes the noun driver and is therefore an adjective.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Parts of speech","question":"In “The farmer harvested the crops early,” what part of speech is “early”?","option_a":"adverb","option_b":"noun","option_c":"pronoun","option_d":"conjunction","correct_answer":"A","explanation":"Early modifies the verb harvested by indicating when the action took place.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Active and passive voice","question":"Choose the passive form of “The health officer inspected the water tank.”","option_a":"The water tank inspected the health officer.","option_b":"The health officer was inspected by the water tank.","option_c":"The water tank was inspected by the health officer.","option_d":"The water tank has inspecting the officer.","correct_answer":"C","explanation":"The object becomes the subject and the past simple passive is was inspected.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Active and passive voice","question":"Which sentence is in the active voice?","option_a":"The bridge was repaired by local workers.","option_b":"Local workers repaired the bridge.","option_c":"The bridge is being repaired.","option_d":"The bridge had been repaired.","correct_answer":"B","explanation":"The subject local workers performs the action repaired.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Conjunctions","question":"Which conjunction best completes: “We left early ___ we could avoid the evening traffic”?","option_a":"although","option_b":"unless","option_c":"whereas","option_d":"so that","correct_answer":"D","explanation":"So that introduces the purpose for leaving early.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Conjunctions","question":"Choose the best connector: “The road was muddy; ___, the bus reached the village.”","option_a":"nevertheless","option_b":"therefore","option_c":"for example","option_d":"similarly","correct_answer":"A","explanation":"Nevertheless signals contrast between the muddy road and the successful arrival.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Sentence types","question":"“Please keep the laboratory door closed.” is what type of sentence?","option_a":"interrogative","option_b":"imperative","option_c":"exclamatory","option_d":"conditional","correct_answer":"B","explanation":"The sentence gives a polite instruction, so it is imperative.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Punctuation","question":"Which punctuation mark should end “What a remarkable performance ___”","option_a":"?","option_b":";","option_c":"!","option_d":".","correct_answer":"C","explanation":"An exclamation mark conveys the strong feeling in this exclamatory sentence.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Punctuation","question":"Which sentence uses the apostrophe correctly?","option_a":"The girls’ bags were placed beside the bench.","option_b":"The girl’s bags were placed beside the bench.","option_c":"The girls bag’s were placed beside the bench.","option_d":"The girls bags’ were placed beside the bench.","correct_answer":"A","explanation":"Girls is plural and the apostrophe after s shows that the bags belong to the girls.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Punctuation","question":"Which sentence uses a semicolon correctly?","option_a":"The bus arrived; because the road was clear.","option_b":"The bus arrived; the passengers boarded calmly.","option_c":"The; bus arrived and the passengers boarded.","option_d":"The bus; arrived, the passengers boarded.","correct_answer":"B","explanation":"A semicolon can join two closely related independent clauses.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Vocabulary in context","question":"A “reluctant” pupil is one who is ___ to volunteer.","option_a":"eager","option_b":"certain","option_c":"prepared","option_d":"unwilling","correct_answer":"D","explanation":"Reluctant means unwilling or hesitant.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Vocabulary in context","question":"If a witness gives a “precise” account, the account is ___.","option_a":"exact and clear","option_b":"very lengthy","option_c":"mostly humorous","option_d":"secretly written","correct_answer":"A","explanation":"Precise means exact and clearly defined.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Synonyms","question":"Which word is closest in meaning to “scarce”?","option_a":"common","option_b":"plentiful","option_c":"rare","option_d":"ordinary","correct_answer":"C","explanation":"Scarce means not plentiful or difficult to obtain.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Antonyms","question":"Choose the opposite of “expand.”","option_a":"increase","option_b":"contract","option_c":"extend","option_d":"enlarge","correct_answer":"B","explanation":"Contract means to become smaller, the opposite of expand.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Idioms","question":"If a coach tells a player to “keep an eye on” the equipment, the player should ___.","option_a":"sell it","option_b":"repair it","option_c":"hide it","option_d":"watch it carefully","correct_answer":"D","explanation":"Keep an eye on means to watch or monitor something.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Idioms","question":"To “break the ice” at a meeting means to ___.","option_a":"make people feel more relaxed","option_b":"end the meeting suddenly","option_c":"criticise the chairperson","option_d":"leave without speaking","correct_answer":"A","explanation":"The idiom means to reduce initial awkwardness and encourage conversation.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Figures of speech","question":"“The goalkeeper was a wall during the match” is an example of ___.","option_a":"simile","option_b":"metaphor","option_c":"pun","option_d":"alliteration","correct_answer":"B","explanation":"The goalkeeper is directly described as a wall to suggest strong defence.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Figures of speech","question":"“The leaves danced in the harmattan breeze” illustrates ___.","option_a":"hyperbole","option_b":"irony","option_c":"personification","option_d":"euphemism","correct_answer":"C","explanation":"The leaves are given the human action of dancing.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Figures of speech","question":"“She ran like the wind” is a ___.","option_a":"metaphor","option_b":"irony","option_c":"personification","option_d":"simile","correct_answer":"D","explanation":"Like explicitly compares her speed with the wind, forming a simile.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Concord","question":"Neither the teachers nor the headmaster ___ available at noon.","option_a":"was","option_b":"were","option_c":"are","option_d":"have been","correct_answer":"A","explanation":"With neither…nor, the verb agrees with the nearer subject, headmaster, which is singular.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Concord","question":"A number of residents ___ for the community meeting.","option_a":"is waiting","option_b":"was waiting","option_c":"are waiting","option_d":"has waited","correct_answer":"C","explanation":"A number of means several and takes a plural verb.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Concord","question":"The committee ___ submitted its report.","option_a":"have","option_b":"has","option_c":"were","option_d":"are","correct_answer":"B","explanation":"When committee is treated as one body, it takes the singular verb has.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Pronouns","question":"Chika and ___ represented the class at the quiz.","option_a":"me","option_b":"myself","option_c":"mine","option_d":"I","correct_answer":"D","explanation":"I is the subject pronoun forming the compound subject Chika and I.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Pronouns","question":"The twins prepared the presentation by ___.","option_a":"themselves","option_b":"theirselves","option_c":"themself","option_d":"their own","correct_answer":"A","explanation":"The plural reflexive pronoun for the twins is themselves.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Relative clauses","question":"The nurse ___ treated the injured player was thanked by the school.","option_a":"which","option_b":"whose","option_c":"who","option_d":"whom","correct_answer":"C","explanation":"Who is the subject relative pronoun referring to the person nurse.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Relative clauses","question":"This is the classroom ___ windows face the football field.","option_a":"who","option_b":"whose","option_c":"whom","option_d":"which’s","correct_answer":"B","explanation":"Whose indicates possession: the windows belong to the classroom.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Conditionals","question":"If the rain ___ before noon, the match will continue.","option_a":"stopped","option_b":"will stop","option_c":"would stop","option_d":"stops","correct_answer":"D","explanation":"In the first conditional, the if-clause uses the present simple.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Conditionals","question":"If I had known about the change, I ___ earlier.","option_a":"would have left","option_b":"will leave","option_c":"left","option_d":"would leave","correct_answer":"A","explanation":"The third conditional uses would have plus a past participle for an unreal past result.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Question tags","question":"“Let’s review the safety rules, ___?”","option_a":"will we","option_b":"do we","option_c":"shall we","option_d":"aren’t we","correct_answer":"C","explanation":"The conventional tag after let’s is shall we.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Question tags","question":"“You seldom visit the museum, ___?”","option_a":"do you","option_b":"don’t you","option_c":"did you","option_d":"aren’t you","correct_answer":"B","explanation":"Seldom has a negative sense, so the tag is positive: do you.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Direct and indirect speech","question":"Musa asked, “Where is the clinic?” Choose the reported form.","option_a":"Musa asked where is the clinic.","option_b":"Musa asked where was the clinic?","option_c":"Musa asked where the clinic is?","option_d":"Musa asked where the clinic was.","correct_answer":"D","explanation":"Reported questions use statement word order and backshift was.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Direct and indirect speech","question":"The teacher said, “Do not waste water.” Choose the reported form.","option_a":"The teacher warned us not to waste water.","option_b":"The teacher said us do not waste water.","option_c":"The teacher asked that we did not wasted water.","option_d":"The teacher warned us to not wasted water.","correct_answer":"A","explanation":"A negative command is commonly reported with warned/told plus object and not to.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Spelling","question":"Which word is correctly spelt?","option_a":"accomodation","option_b":"acommodation","option_c":"accommodation","option_d":"accommadation","correct_answer":"C","explanation":"Accommodation has double c and double m.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Spelling","question":"Choose the correctly spelt word.","option_a":"priviledge","option_b":"privilege","option_c":"privelege","option_d":"privillage","correct_answer":"B","explanation":"Privilege is spelt p-r-i-v-i-l-e-g-e.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Word stress","question":"In the noun “record,” which syllable is normally stressed?","option_a":"second syllable","option_b":"both equally","option_c":"final sound only","option_d":"first syllable","correct_answer":"D","explanation":"The noun RE-cord normally carries stress on its first syllable.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Word stress","question":"Which syllable is stressed in the verb “permit”?","option_a":"second syllable","option_b":"first syllable","option_c":"both syllables equally","option_d":"neither syllable","correct_answer":"A","explanation":"The verb per-MIT normally carries stress on the second syllable.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Comprehension skills","question":"When reading a passage, what does “infer” mean?","option_a":"copy a sentence exactly","option_b":"count the paragraphs","option_c":"draw a conclusion from clues","option_d":"replace every unfamiliar word","correct_answer":"C","explanation":"An inference is a conclusion supported by details in the text.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Comprehension skills","question":"Which note-taking method best captures a long passage for later revision?","option_a":"Copy every sentence without selection.","option_b":"Record the main ideas and supporting points briefly.","option_c":"Write only unfamiliar words.","option_d":"Replace the author’s argument with a guess.","correct_answer":"B","explanation":"Effective notes condense the main ideas and relevant supporting details.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Formal writing","question":"Which opening is most suitable for a formal letter to a local government chairperson?","option_a":"Hi there, what’s happening?","option_b":"My dear friend,","option_c":"Hello chairman!!!","option_d":"Dear Sir/Madam,","correct_answer":"D","explanation":"Dear Sir/Madam is a suitable formal salutation when the recipient’s name is unknown.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Paragraph development","question":"Which sentence is most likely to be the topic sentence of a paragraph about clean water?","option_a":"Access to safe water improves public health in several ways.","option_b":"The blue bucket is beside the tap.","option_c":"Yesterday was Tuesday.","option_d":"My pen has a red cap.","correct_answer":"A","explanation":"It states the central idea that the following supporting details can develop.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Register","question":"Which word belongs most directly to the vocabulary of farming?","option_a":"latitude","option_b":"invoice","option_c":"irrigation","option_d":"ballot","correct_answer":"C","explanation":"Irrigation is the artificial supply of water to crops.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"English Language","topic":"Register","question":"In a hospital, a “ward” is best understood as ___.","option_a":"a court ruling","option_b":"a room or unit for patients","option_c":"a farm tool","option_d":"a school subject","correct_answer":"B","explanation":"A hospital ward is a section where patients receive care.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Fractions","question":"Evaluate 3/4 + 2/3.","option_a":"17/12","option_b":"5/7","option_c":"13/12","option_d":"7/12","correct_answer":"A","explanation":"Using denominator 12 gives 9/12 + 8/12 = 17/12.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Fractions","question":"Simplify 5/6 − 1/4.","option_a":"1/2","option_b":"7/12","option_c":"2/10","option_d":"4/12","correct_answer":"B","explanation":"A common denominator of 12 gives 10/12 − 3/12 = 7/12.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Ratio","question":"A mixture uses 2 cups of concentrate for every 5 cups of water. How much concentrate is needed for 20 cups of water?","option_a":"4 cups","option_b":"5 cups","option_c":"8 cups","option_d":"10 cups","correct_answer":"C","explanation":"The scale factor is 20 ÷ 5 = 4, so concentrate needed is 2 × 4 = 8 cups.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Percentages","question":"A school bag costs ₦18,000 before a 10% discount. What is its sale price?","option_a":"₦1,800","option_b":"₦16,000","option_c":"₦17,000","option_d":"₦16,200","correct_answer":"D","explanation":"Ten percent of ₦18,000 is ₦1,800; subtracting gives ₦16,200.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Percentages","question":"A student scores 42 marks out of 60. What percentage is this?","option_a":"70%","option_b":"65%","option_c":"72%","option_d":"80%","correct_answer":"A","explanation":"42/60 × 100 = 70%.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Ratio","question":"Divide ₦7,200 in the ratio 5:3. What is the larger share?","option_a":"₦2,700","option_b":"₦4,500","option_c":"₦4,800","option_d":"₦5,400","correct_answer":"B","explanation":"There are 8 parts; the larger share is 5/8 × ₦7,200 = ₦4,500.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Standard form","question":"Write 0.00056 in standard form.","option_a":"5.6 × 10⁴","option_b":"56 × 10⁻⁵","option_c":"5.6 × 10⁻⁴","option_d":"0.56 × 10⁻³","correct_answer":"C","explanation":"Moving the decimal four places right gives 5.6, so the power is −4.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Standard form","question":"Evaluate (3 × 10⁵)(2 × 10³).","option_a":"6 × 10⁸","option_b":"5 × 10⁸","option_c":"6 × 10¹⁵","option_d":"6 × 10⁸⁻³","correct_answer":"A","explanation":"Multiply coefficients and add powers: 3 × 2 = 6 and 10⁵ × 10³ = 10⁸.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Indices","question":"Simplify 2³ × 2⁴.","option_a":"2¹²","option_b":"2⁷","option_c":"4⁷","option_d":"2¹","correct_answer":"B","explanation":"For equal bases, add the indices: 3 + 4 = 7.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Indices","question":"Evaluate 27^(2/3).","option_a":"3","option_b":"6","option_c":"9","option_d":"18","correct_answer":"C","explanation":"The cube root of 27 is 3, and 3² = 9.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Logarithms","question":"Evaluate log₁₀ 0.01.","option_a":"−1","option_b":"2","option_c":"−10","option_d":"−2","correct_answer":"D","explanation":"Since 0.01 = 10⁻², its common logarithm is −2.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Algebraic expressions","question":"Simplify 4a − 3b + 2a + 5b.","option_a":"6a + 2b","option_b":"6a − 8b","option_c":"2a + 2b","option_d":"6ab","correct_answer":"A","explanation":"Collect like terms: 4a + 2a = 6a and −3b + 5b = 2b.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Algebraic expressions","question":"Expand 3(2x − 5).","option_a":"6x − 5","option_b":"6x − 15","option_c":"5x − 15","option_d":"6x + 15","correct_answer":"B","explanation":"Multiply each term in the bracket by 3.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Factorisation","question":"Factorise x² + 7x + 12.","option_a":"(x + 6)(x + 2)","option_b":"(x − 3)(x − 4)","option_c":"(x + 3)(x + 4)","option_d":"(x + 12)(x + 1)","correct_answer":"C","explanation":"The numbers 3 and 4 have product 12 and sum 7.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Linear equations","question":"Solve 5x + 7 = 32.","option_a":"x = 7","option_b":"x = 4","option_c":"x = 6","option_d":"x = 5","correct_answer":"D","explanation":"Subtract 7 to get 5x = 25, then divide by 5.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Simultaneous equations","question":"If x + y = 11 and x − y = 3, find x.","option_a":"7","option_b":"4","option_c":"8","option_d":"14","correct_answer":"A","explanation":"Adding the equations gives 2x = 14, so x = 7.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Linear inequalities","question":"Solve −2x > 8.","option_a":"x > −4","option_b":"x < −4","option_c":"x > 4","option_d":"x < 4","correct_answer":"B","explanation":"Dividing by a negative reverses the inequality sign, giving x < −4.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Sequences","question":"Find the 12th term of 4, 7, 10, 13, …","option_a":"34","option_b":"35","option_c":"37","option_d":"40","correct_answer":"C","explanation":"The sequence has first term 4 and difference 3; term 12 is 4 + 11×3 = 37.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Sequences","question":"What is the next term: 3, 6, 12, 24, ___?","option_a":"30","option_b":"36","option_c":"42","option_d":"48","correct_answer":"D","explanation":"Each term is twice the previous one, so 24 × 2 = 48.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Sets","question":"If U = {1,2,3,4,5,6} and A = {2,4,6}, how many elements are in A′?","option_a":"3","option_b":"2","option_c":"4","option_d":"6","correct_answer":"A","explanation":"A′ contains elements of U not in A: {1,3,5}.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Sets","question":"In a group of 40 learners, 24 play football, 18 play volleyball and 8 play both. How many play at least one?","option_a":"34","option_b":"32","option_c":"42","option_d":"50","correct_answer":"A","explanation":"Using n(F∪V)=24+18−8 gives 34.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Functions","question":"If f(x)=3x−2, find f(5).","option_a":"11","option_b":"13","option_c":"15","option_d":"17","correct_answer":"B","explanation":"Substitute 5: f(5)=3×5−2=13.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Coordinate geometry","question":"Find the midpoint of (2, −1) and (8, 5).","option_a":"(5, 2)","option_b":"(6, 4)","option_c":"(3, 2)","option_d":"(10, 4)","correct_answer":"A","explanation":"Average the coordinates: ((2+8)/2, (−1+5)/2) = (5,2).","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Coordinate geometry","question":"Find the distance between (1, 2) and (4, 6).","option_a":"4","option_b":"5","option_c":"6","option_d":"7","correct_answer":"B","explanation":"Distance = √((4−1)²+(6−2)²)=√25=5.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Angles","question":"Two angles on a straight line are (3x)° and (2x)°. Find x.","option_a":"18","option_b":"30","option_c":"36","option_d":"45","correct_answer":"C","explanation":"Angles on a straight line sum to 180°, so 5x=180° and x=36°.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Angles","question":"An angle is 38°. What is its complementary angle?","option_a":"52°","option_b":"142°","option_c":"62°","option_d":"38°","correct_answer":"A","explanation":"Complementary angles add to 90°, so 90°−38°=52°.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Polygons","question":"What is the sum of the interior angles of a hexagon?","option_a":"540°","option_b":"720°","option_c":"900°","option_d":"1080°","correct_answer":"B","explanation":"For n=6, the sum is (n−2)×180°=720°.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Perimeter","question":"A rectangle is 12 cm long and 7 cm wide. Find its perimeter.","option_a":"19 cm","option_b":"38 cm","option_c":"84 cm","option_d":"42 cm","correct_answer":"B","explanation":"Perimeter = 2(12+7)=38 cm.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Area","question":"Find the area of a triangle with base 14 cm and perpendicular height 9 cm.","option_a":"126 cm²","option_b":"63 cm²","option_c":"46 cm²","option_d":"23 cm²","correct_answer":"B","explanation":"Area = ½×14×9 = 63 cm².","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Circle geometry","question":"A circle has radius 7 cm. Using π=22/7, find its circumference.","option_a":"22 cm","option_b":"44 cm","option_c":"154 cm","option_d":"308 cm","correct_answer":"B","explanation":"Circumference = 2πr = 2×22/7×7 = 44 cm.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Volume","question":"Find the volume of a cuboid measuring 8 cm by 5 cm by 3 cm.","option_a":"16 cm³","option_b":"40 cm³","option_c":"120 cm³","option_d":"240 cm³","correct_answer":"C","explanation":"Volume = length×width×height = 8×5×3 = 120 cm³.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Surface area","question":"Find the total surface area of a cube of side 4 cm.","option_a":"16 cm²","option_b":"64 cm²","option_c":"80 cm²","option_d":"96 cm²","correct_answer":"D","explanation":"A cube has six square faces: 6×4²=96 cm².","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Trigonometry","question":"In a right triangle, the opposite and hypotenuse are 8 cm and 10 cm. Find sin θ.","option_a":"4/5","option_b":"5/4","option_c":"3/5","option_d":"4/3","correct_answer":"A","explanation":"Sine is opposite over hypotenuse: 8/10 = 4/5.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Trigonometry","question":"If tan θ = 3/4 for an acute angle, what is sin θ?","option_a":"4/5","option_b":"3/5","option_c":"3/4","option_d":"4/3","correct_answer":"B","explanation":"The 3-4-5 triangle gives opposite 3 and hypotenuse 5, so sin θ=3/5.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Bearings","question":"A pupil walks due east from the school. What is the three-figure bearing?","option_a":"090°","option_b":"180°","option_c":"270°","option_d":"000°","correct_answer":"A","explanation":"Bearings are measured clockwise from north; east is 090°.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Statistics","question":"Find the mean of 4, 6, 8, 10 and 12.","option_a":"6","option_b":"7","option_c":"8","option_d":"10","correct_answer":"C","explanation":"The sum is 40 and there are five values, so the mean is 8.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Statistics","question":"Find the median of 3, 9, 4, 11, 7.","option_a":"4","option_b":"7","option_c":"8","option_d":"9","correct_answer":"B","explanation":"In order the values are 3,4,7,9,11; the middle is 7.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Statistics","question":"Find the mode of 2, 5, 5, 6, 7, 5, 8.","option_a":"2","option_b":"6","option_c":"7","option_d":"5","correct_answer":"D","explanation":"Five occurs more often than any other value.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Probability","question":"A fair die is rolled once. What is the probability of getting a number greater than 4?","option_a":"1/3","option_b":"1/2","option_c":"2/3","option_d":"5/6","correct_answer":"A","explanation":"The favourable outcomes are 5 and 6: 2/6 = 1/3.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Probability","question":"A bag contains 3 red and 5 blue counters. What is the probability of selecting a red counter?","option_a":"5/8","option_b":"3/8","option_c":"1/3","option_d":"3/5","correct_answer":"B","explanation":"There are 3 red counters among 8 counters, giving 3/8.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Variation","question":"y varies directly as x. If y=15 when x=5, find y when x=8.","option_a":"18","option_b":"20","option_c":"24","option_d":"30","correct_answer":"C","explanation":"The constant is 15/5=3, so y=3×8=24.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Variation","question":"z varies inversely as t. If z=12 when t=2, find z when t=8.","option_a":"2","option_b":"3","option_c":"6","option_d":"48","correct_answer":"B","explanation":"For inverse variation zt is constant: 12×2=24, so z=24/8=3.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Commercial arithmetic","question":"Find the simple interest on ₦50,000 at 8% per annum for 2 years.","option_a":"₦4,000","option_b":"₦8,000","option_c":"₦10,000","option_d":"₦16,000","correct_answer":"B","explanation":"I=PRT/100=50,000×8×2/100=₦8,000.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Commercial arithmetic","question":"A trader buys a kettle for ₦6,400 and sells it for ₦8,000. Find the profit percentage on cost.","option_a":"20%","option_b":"25%","option_c":"16%","option_d":"125%","correct_answer":"B","explanation":"Profit=₦1,600; profit percentage=1,600/6,400×100=25%.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Approximation","question":"Round 0.006784 to 3 significant figures.","option_a":"0.00678","option_b":"0.00680","option_c":"0.00679","option_d":"0.00700","correct_answer":"A","explanation":"The first three significant digits are 6,7,8; the next digit is 4, so it stays 0.00678.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Speed","question":"A bus covers 180 km in 3 hours. Find its average speed.","option_a":"50 km/h","option_b":"60 km/h","option_c":"90 km/h","option_d":"540 km/h","correct_answer":"B","explanation":"Average speed = distance/time = 180/3 = 60 km/h.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Matrices","question":"If A=[[2,1],[0,3]] and B=[[4,5],[6,−1]], find the top-left entry of A+B.","option_a":"2","option_b":"4","option_c":"6","option_d":"8","correct_answer":"C","explanation":"Corresponding entries are added; the top-left entry is 2+4=6.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Variation","question":"A map scale is 1:50,000. What ground distance does 6 cm represent?","option_a":"300 m","option_b":"3 km","option_c":"30 km","option_d":"300 km","correct_answer":"B","explanation":"6×50,000=300,000 cm = 3,000 m = 3 km.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Surds","question":"Simplify √72.","option_a":"6√2","option_b":"4√3","option_c":"8√3","option_d":"12√2","correct_answer":"A","explanation":"√72=√(36×2)=6√2.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"General Mathematics","topic":"Algebraic fractions","question":"Simplify (x² − 9)/(x − 3), where x ≠ 3.","option_a":"x − 3","option_b":"x + 3","option_c":"x² + 3","option_d":"1","correct_answer":"B","explanation":"Factor the numerator as (x−3)(x+3) and cancel x−3, valid when x is not 3.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Computer systems","question":"Which component executes instructions and controls most processing in a computer?","option_a":"keyboard","option_b":"central processing unit","option_c":"monitor","option_d":"printer","correct_answer":"B","explanation":"The CPU processes instructions and coordinates system operations.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Computer systems","question":"Which memory loses its contents when the computer is switched off?","option_a":"ROM","option_b":"SSD","option_c":"RAM","option_d":"flash drive","correct_answer":"C","explanation":"RAM is volatile working memory and loses stored contents without power.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Storage","question":"Which is an example of secondary storage?","option_a":"cache","option_b":"register","option_c":"RAM","option_d":"solid-state drive","correct_answer":"D","explanation":"An SSD retains files without power and is secondary storage.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Input and output","question":"Which device converts a paper photograph into digital data?","option_a":"scanner","option_b":"speaker","option_c":"projector","option_d":"plotter","correct_answer":"A","explanation":"A scanner captures an image and converts it to digital form.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Input and output","question":"Which device is primarily an output device?","option_a":"microphone","option_b":"monitor","option_c":"barcode reader","option_d":"keyboard","correct_answer":"B","explanation":"A monitor displays processed information to the user.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Software","question":"Which software manages memory, files and peripheral devices?","option_a":"word processor","option_b":"spreadsheet","option_c":"operating system","option_d":"presentation package","correct_answer":"C","explanation":"An operating system manages hardware resources and provides common services.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Software","question":"A student uses a word processor to prepare a letter. This is what type of software?","option_a":"firmware","option_b":"system software","option_c":"device driver","option_d":"application software","correct_answer":"D","explanation":"A word processor is application software for a user task.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Data representation","question":"How many bits are in one byte?","option_a":"8","option_b":"4","option_c":"16","option_d":"1024","correct_answer":"A","explanation":"A byte consists of eight bits.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Data representation","question":"What is the binary equivalent of decimal 10?","option_a":"1001","option_b":"1010","option_c":"1100","option_d":"1110","correct_answer":"B","explanation":"10 in decimal equals 8+2, represented as 1010 in binary.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Data representation","question":"What is decimal 13 written in binary?","option_a":"1011","option_b":"1100","option_c":"1101","option_d":"1110","correct_answer":"C","explanation":"13=8+4+1, giving binary 1101.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Data representation","question":"Convert binary 10011 to decimal.","option_a":"17","option_b":"18","option_c":"19","option_d":"20","correct_answer":"C","explanation":"10011₂=16+2+1=19.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Data representation","question":"What is the largest unsigned value represented by 5 bits?","option_a":"15","option_b":"16","option_c":"30","option_d":"31","correct_answer":"D","explanation":"Five bits represent 0 through 2⁵−1, so the maximum is 31.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Logic","question":"A logical AND operation returns true when ___.","option_a":"both inputs are true","option_b":"either input is true","option_c":"both inputs are false","option_d":"the inputs differ","correct_answer":"A","explanation":"AND is true only when both input conditions are true.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Logic","question":"If P is true, what is the value of NOT P?","option_a":"true","option_b":"false","option_c":"both values","option_d":"undefined","correct_answer":"B","explanation":"NOT reverses a Boolean value, so NOT true is false.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Algorithms","question":"In an algorithm, a decision based on a condition uses which structure?","option_a":"sequence","option_b":"output","option_c":"selection","option_d":"comment","correct_answer":"C","explanation":"Selection chooses a path according to whether a condition is true or false.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Algorithms","question":"A loop that repeats while a condition remains true is a form of ___.","option_a":"output","option_b":"selection only","option_c":"data entry","option_d":"iteration","correct_answer":"D","explanation":"Iteration repeats a set of instructions, often while a condition holds.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Algorithms","question":"What is the purpose of a flowchart terminator symbol?","option_a":"to show the start or end","option_b":"to show a calculation","option_c":"to show a decision","option_d":"to show stored data","correct_answer":"A","explanation":"The oval terminator marks the beginning or end of a flowchart.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Algorithms","question":"In a flowchart, a diamond usually represents ___.","option_a":"input/output","option_b":"a decision","option_c":"a process","option_d":"a connector label","correct_answer":"B","explanation":"A diamond is the standard decision symbol, usually with branches.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Programming","question":"Which data type best stores the value 27 without a decimal part?","option_a":"Boolean","option_b":"character","option_c":"integer","option_d":"string only","correct_answer":"C","explanation":"An integer represents whole numbers such as 27.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Programming","question":"Which data type is most suitable for storing a learner’s first name?","option_a":"integer","option_b":"Boolean","option_c":"floating point","option_d":"string","correct_answer":"D","explanation":"A string stores a sequence of text characters.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Programming","question":"What is a variable used for in a program?","option_a":"to store a value that may be used or changed","option_b":"to print paper","option_c":"to connect a monitor physically","option_d":"to prevent all input","correct_answer":"A","explanation":"A variable names a storage location for data used by a program.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Programming","question":"Which operator commonly tests whether two values are equal?","option_a":"+","option_b":"==","option_c":"/","option_d":"%","correct_answer":"B","explanation":"In many programming languages, == compares two values for equality.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Programming","question":"A syntax error is usually caused by ___.","option_a":"a slow internet connection","option_b":"an empty printer tray","option_c":"code that breaks the language’s grammar rules","option_d":"a monitor with low brightness","correct_answer":"C","explanation":"Syntax errors occur when source code violates the programming language grammar.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Spreadsheets","question":"In a spreadsheet, the intersection of a row and a column is called a ___.","option_a":"workbook","option_b":"formula","option_c":"range","option_d":"cell","correct_answer":"D","explanation":"A cell is identified by its column letter and row number.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Spreadsheets","question":"Which formula adds the values in cells C2 through C8?","option_a":"=ADD(C2:C8)","option_b":"=SUM(C2:C8)","option_c":"=TOTAL(C2-C8)","option_d":"=PLUS(C2:C8)","correct_answer":"B","explanation":"SUM adds the numeric values in the specified range.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Spreadsheets","question":"A cell contains =B2*D2. What operation does the asterisk perform?","option_a":"addition","option_b":"division","option_c":"multiplication","option_d":"subtraction","correct_answer":"C","explanation":"The asterisk is the multiplication operator in spreadsheet formulas.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Spreadsheets","question":"Which chart is generally suitable for comparing sales across five months?","option_a":"pie chart only","option_b":"scatter plot","option_c":"map chart","option_d":"bar or column chart","correct_answer":"D","explanation":"Bars or columns make comparisons among discrete monthly categories clear.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Spreadsheets","question":"What does sorting a table by surname in ascending order do?","option_a":"arranges names from A to Z","option_b":"deletes repeated names","option_c":"changes every value to a formula","option_d":"hides the surname column","correct_answer":"A","explanation":"Ascending alphabetical sorting orders the entries from A to Z.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Databases","question":"In a student table, which field is best suited to be a primary key?","option_a":"class name","option_b":"unique admission number","option_c":"surname","option_d":"house colour","correct_answer":"B","explanation":"A primary key uniquely identifies each record; an admission number can do so.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Databases","question":"A foreign key is used mainly to ___.","option_a":"format a report","option_b":"sort a spreadsheet","option_c":"link a record to a related table","option_d":"encrypt a password","correct_answer":"C","explanation":"A foreign key references a key in another table to establish a relationship.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Databases","question":"Which database field type is suitable for a date of birth?","option_a":"currency","option_b":"Boolean","option_c":"long text only","option_d":"date","correct_answer":"D","explanation":"A date field stores dates in a form that can be sorted and validated.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Networks","question":"What does a router mainly do on a network?","option_a":"forwards data between networks","option_b":"prints documents","option_c":"stores keyboard strokes","option_d":"converts sound to text","correct_answer":"A","explanation":"A router directs packets between networks, such as a home network and the internet.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Networks","question":"A school computer connected to a shared printer over the school building uses a ___.","option_a":"PAN","option_b":"LAN","option_c":"WAN","option_d":"satellite orbit","correct_answer":"B","explanation":"A local area network connects devices within a limited site such as a school.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Networks","question":"Which protocol is commonly used to transfer web pages securely?","option_a":"FTP","option_b":"HTTP only","option_c":"HTTPS","option_d":"SMTP","correct_answer":"C","explanation":"HTTPS protects web communication using encryption through TLS.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Internet","question":"Which service translates a domain name into an IP address?","option_a":"HTML","option_b":"USB","option_c":"GPS","option_d":"DNS","correct_answer":"D","explanation":"DNS resolves human-readable domain names to IP addresses.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Cybersecurity","question":"A message falsely claims a learner’s account will close and asks for a password through a link. This is likely ___.","option_a":"phishing","option_b":"compression","option_c":"formatting","option_d":"defragmentation","correct_answer":"A","explanation":"Phishing uses deceptive messages to trick people into revealing sensitive information.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Cybersecurity","question":"Which is the strongest password practice?","option_a":"reuse a short familiar password","option_b":"use a long unique passphrase and enable multi-factor authentication","option_c":"write a password on a classroom wall","option_d":"send it to a friend for safekeeping","correct_answer":"B","explanation":"A unique strong passphrase and a second authentication factor reduce account compromise risk.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Cybersecurity","question":"Why should software updates be installed from trusted sources?","option_a":"to increase screen size","option_b":"to remove the need for backups","option_c":"they can fix security weaknesses","option_d":"they make every password public","correct_answer":"C","explanation":"Updates often patch vulnerabilities as well as correct bugs.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Cybersecurity","question":"What is a sensible response to an unexpected attachment from an unknown sender?","option_a":"open it to identify the sender","option_b":"forward it to all classmates","option_c":"disable antivirus first","option_d":"do not open it and report or verify the message","correct_answer":"D","explanation":"Unknown attachments may contain malware; verify through a trusted channel and report suspicious mail.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Digital citizenship","question":"Which action respects another person’s copyright?","option_a":"cite the source and obtain permission where required","option_b":"remove the author’s name and repost the work","option_c":"claim every online image is free","option_d":"sell a copied textbook as your own","correct_answer":"A","explanation":"Attribution and permission respect creators’ rights and applicable licence terms.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Digital citizenship","question":"Before posting a classmate’s photograph online, a learner should ___.","option_a":"tag every contact","option_b":"ask the classmate’s permission","option_c":"add an insulting caption","option_d":"publish the person’s phone number","correct_answer":"B","explanation":"Consent helps protect another person’s privacy and dignity.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Data ethics","question":"Why should a school collect only the personal data it needs for a stated purpose?","option_a":"to make every record public","option_b":"to avoid using any security","option_c":"to reduce privacy risks and unnecessary exposure","option_d":"to prevent students from learning","correct_answer":"C","explanation":"Data minimisation limits unnecessary collection and lowers potential privacy harm.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"File management","question":"Which filename is most useful for a science report saved on 12 March 2026?","option_a":"newfilefinalfinal","option_b":"report","option_c":"x1","option_d":"SS1_Biology_Report_2026-03-12","correct_answer":"D","explanation":"A descriptive filename with subject and date makes a file easier to identify.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"File management","question":"Which file extension commonly identifies a portable document format file?","option_a":".pptx","option_b":".pdf","option_c":".xlsx","option_d":".mp3","correct_answer":"B","explanation":"The .pdf extension identifies a Portable Document Format file.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Computer care","question":"Which practice helps prevent damage from overheating?","option_a":"cover ventilation openings","option_b":"place the laptop on a soft bed","option_c":"keep vents unobstructed and use a firm surface","option_d":"leave the device in direct sun","correct_answer":"C","explanation":"Clear vents and a firm surface allow heat to escape.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Computer care","question":"Why should a user back up important school files?","option_a":"to make the files impossible to edit","option_b":"to remove all passwords","option_c":"to increase the monitor resolution","option_d":"to recover work if the original is lost or damaged","correct_answer":"D","explanation":"A separate backup allows recovery after accidental deletion, device failure or damage.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Assistive technology","question":"Which feature can read on-screen text aloud for a user with low vision?","option_a":"screen reader","option_b":"spell checker","option_c":"disk cleanup","option_d":"file compressor","correct_answer":"A","explanation":"A screen reader presents interface and document text through speech or braille output.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Emerging technology","question":"A sensor automatically switches a water pump on when a tank is low. This is an example of ___.","option_a":"desktop publishing","option_b":"automation using input data","option_c":"manual data entry","option_d":"word processing","correct_answer":"B","explanation":"The sensor supplies input and the system automatically triggers an action.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Emerging technology","question":"Which device is most suitable for measuring room temperature in an automated system?","option_a":"temperature sensor","option_b":"barcode printer","option_c":"speaker","option_d":"joystick","correct_answer":"A","explanation":"A temperature sensor detects heat level and supplies readings to the system.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Digital Technologies","topic":"Data communication","question":"What is the main purpose of encryption when sending a file online?","option_a":"to increase the file size","option_b":"to convert readable data into a protected form","option_c":"to delete the recipient copy","option_d":"to make the network wireless","correct_answer":"B","explanation":"Encryption encodes information so unauthorised parties cannot readily read it.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Nigerian constitution","question":"Which statement best describes a constitution?","option_a":"a list of private family rules","option_b":"a timetable for school lessons","option_c":"the fundamental framework for governing a state","option_d":"a record of market prices","correct_answer":"C","explanation":"A constitution sets out core government structures, powers and citizens’ rights.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Nigerian constitution","question":"Nigeria’s 1999 Constitution provides for how many tiers of government?","option_a":"two","option_b":"four","option_c":"five","option_d":"three","correct_answer":"D","explanation":"The constitution recognises federal, state and local government tiers.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Separation of powers","question":"Which arm of government interprets laws and settles legal disputes?","option_a":"judiciary","option_b":"legislature","option_c":"executive","option_d":"civil service","correct_answer":"A","explanation":"Courts in the judiciary interpret and apply the law in cases.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Separation of powers","question":"At the federal level, which body exercises legislative power?","option_a":"Federal Executive Council","option_b":"National Assembly","option_c":"Supreme Court","option_d":"INEC","correct_answer":"B","explanation":"The Senate and House of Representatives together form the National Assembly.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Federalism","question":"A key feature of federalism is ___.","option_a":"one level controls every local matter","option_b":"the absence of a constitution","option_c":"constitutional sharing of powers between levels of government","option_d":"rule by the armed forces","correct_answer":"C","explanation":"Federalism divides powers constitutionally between central and constituent governments.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Rule of law","question":"The principle that public officers are subject to the law is part of ___.","option_a":"military command","option_b":"traditional title","option_c":"party supremacy","option_d":"rule of law","correct_answer":"D","explanation":"Rule of law requires government officials as well as citizens to obey the law.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Citizenship","question":"Which is a recognised way of acquiring Nigerian citizenship under the constitution?","option_a":"registration, where constitutional conditions are met","option_b":"buying a voter card","option_c":"being appointed a school prefect","option_d":"owning a shop in Nigeria","correct_answer":"A","explanation":"The constitution provides for citizenship by birth, registration and naturalisation under specified conditions.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Citizenship","question":"Which responsibility supports peaceful community life?","option_a":"ignoring lawful public notices","option_b":"obeying lawful rules and respecting others’ rights","option_c":"preventing neighbours from voting","option_d":"damaging shared facilities","correct_answer":"B","explanation":"Following lawful rules and respecting rights helps communities function peacefully.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Fundamental rights","question":"Freedom of expression generally allows people to ___.","option_a":"threaten anyone without consequence","option_b":"publish another person’s private password","option_c":"share opinions subject to lawful limits and others’ rights","option_d":"ignore every court order","correct_answer":"C","explanation":"Expression is protected, while lawful limits and the rights of others still apply.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Fundamental rights","question":"Which action is a peaceful way to seek redress for an alleged rights violation?","option_a":"retaliate against the official","option_b":"destroy public property","option_c":"spread an unverified rumour","option_d":"use an appropriate complaint or court process","correct_answer":"D","explanation":"Lawful complaint and judicial processes provide peaceful routes to redress.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Democracy","question":"In a representative democracy, citizens mainly choose representatives through ___.","option_a":"elections","option_b":"inheritance","option_c":"appointment by a foreign state","option_d":"a lottery","correct_answer":"A","explanation":"Elections allow eligible citizens to select public representatives.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Elections","question":"Why is a secret ballot important?","option_a":"it lets officials count a vote twice","option_b":"it protects voter choice from intimidation","option_c":"it removes the need for voter registration","option_d":"it guarantees every candidate wins","correct_answer":"B","explanation":"Ballot secrecy helps voters choose freely without pressure or retaliation.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Electoral process","question":"Which institution conducts federal elections in Nigeria?","option_a":"Nigerian Police Force","option_b":"National Assembly","option_c":"Independent National Electoral Commission","option_d":"Federal High Court","correct_answer":"C","explanation":"INEC is constitutionally responsible for organising federal elections.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Civic participation","question":"A resident who wants a safer pedestrian crossing should first ___.","option_a":"remove road signs","option_b":"block the road indefinitely","option_c":"damage the traffic light","option_d":"petition the relevant local authority with evidence","correct_answer":"D","explanation":"A reasoned petition to the responsible authority is a lawful civic channel.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Accountability","question":"A public officer explains how allocated funds were spent. This demonstrates ___.","option_a":"accountability","option_b":"censorship","option_c":"nepotism","option_d":"secrecy","correct_answer":"A","explanation":"Accountability requires officials to explain and answer for their decisions and use of resources.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Transparency","question":"Publishing a public project budget in an accessible format promotes ___.","option_a":"arbitrary rule","option_b":"transparency","option_c":"voter intimidation","option_d":"separation from citizens","correct_answer":"B","explanation":"Open budget information helps the public see how funds are planned and used.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Public service","question":"The main purpose of a public service is to ___.","option_a":"serve only the family of an office holder","option_b":"raise money for a political party","option_c":"deliver services and implement lawful public policy","option_d":"replace the courts","correct_answer":"C","explanation":"Public servants support government and provide services for the public.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Local government","question":"Which responsibility is commonly associated with local government?","option_a":"printing Nigerian currency","option_b":"foreign policy","option_c":"commanding the armed forces","option_d":"maintaining local markets and community services","correct_answer":"D","explanation":"Local councils commonly handle local services such as markets, sanitation and community infrastructure.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"National symbols","question":"What does Nigeria’s green-white-green flag commonly represent?","option_a":"agriculture and peace","option_b":"oil and military rule","option_c":"three arms of government","option_d":"three political parties","correct_answer":"A","explanation":"Green is commonly associated with agriculture and white with peace.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"National identity","question":"Nigeria’s national anthem and flag are examples of ___.","option_a":"private property","option_b":"national symbols","option_c":"court documents","option_d":"campaign promises","correct_answer":"B","explanation":"National symbols represent the country and can support shared civic identity.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Unity in diversity","question":"Which action best promotes unity among students from different ethnic groups?","option_a":"mocking unfamiliar accents","option_b":"insisting everyone abandon their heritage","option_c":"cooperating and treating classmates fairly","option_d":"excluding classmates from group work","correct_answer":"C","explanation":"Respectful cooperation recognises equal dignity while allowing cultural differences.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Conflict resolution","question":"Two community groups disagree about a shared water point. Which approach is most constructive?","option_a":"spread accusations online","option_b":"use threats to force agreement","option_c":"block access permanently","option_d":"hold a facilitated dialogue and agree on fair use","correct_answer":"D","explanation":"Dialogue can help parties understand needs and agree on a workable arrangement.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Peace education","question":"A bystander sees classmates preparing for a fight. What is the safest helpful response?","option_a":"avoid joining, seek trusted adult help and support de-escalation","option_b":"encourage the fight","option_c":"record and publish it for entertainment","option_d":"bring an object to the scene","correct_answer":"A","explanation":"Avoiding escalation and alerting responsible adults can help protect those involved.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Human rights","question":"Human rights are best described as ___.","option_a":"privileges available only to wealthy people","option_b":"basic entitlements people have by virtue of being human","option_c":"rewards given only to public officers","option_d":"rules that apply only during elections","correct_answer":"B","explanation":"Human rights are basic entitlements grounded in human dignity.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Responsibilities","question":"Which action balances personal freedom with responsibility?","option_a":"playing loud music through the night","option_b":"sharing a neighbour’s private messages","option_c":"enjoying a right while respecting others’ safety and rights","option_d":"refusing every lawful community rule","correct_answer":"C","explanation":"Responsible exercise of freedom takes account of the rights and safety of others.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Rule of law","question":"An arrested person should be treated according to law and given a fair hearing. This reflects ___.","option_a":"collective punishment","option_b":"rule by decree","option_c":"mob justice","option_d":"due process","correct_answer":"D","explanation":"Due process requires fair legal procedures when rights or liberty are at stake.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Justice","question":"Why should a judge be independent when deciding a case?","option_a":"to decide impartially according to law and evidence","option_b":"to follow private instructions from a litigant","option_c":"to campaign for one party","option_d":"to avoid giving reasons for decisions","correct_answer":"A","explanation":"Judicial independence protects impartial decision-making based on law and evidence.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Anti-corruption","question":"A student is asked to pay an unofficial fee for a service already covered by school policy. A responsible response is to ___.","option_a":"pay secretly and demand a reward","option_b":"report the request through a safe, appropriate channel","option_c":"threaten the staff member","option_d":"publish unverified personal details","correct_answer":"B","explanation":"Using an appropriate reporting channel supports accountability and avoids escalation.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Public property","question":"Why should citizens protect public facilities such as clinics and roads?","option_a":"they belong to no one","option_b":"only officials use them","option_c":"they serve shared community needs","option_d":"damage always improves access","correct_answer":"C","explanation":"Public facilities are shared resources that support the wider community.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Environmental citizenship","question":"Which action is a responsible way to reduce blocked drains during rainy season?","option_a":"dump refuse beside the road","option_b":"pour used oil into a gutter","option_c":"remove covers from drains","option_d":"dispose of waste properly and keep drainage channels clear","correct_answer":"D","explanation":"Proper waste disposal reduces blockage and helps water flow through drains.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Community development","question":"Residents volunteer to repair a community reading room. This is an example of ___.","option_a":"community participation","option_b":"electoral malpractice","option_c":"judicial review","option_d":"cultural assimilation","correct_answer":"A","explanation":"Voluntary joint work is community participation in local development.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Volunteering","question":"Which activity is an example of civic volunteering?","option_a":"demanding payment before reporting an emergency","option_b":"helping organise a neighbourhood clean-up","option_c":"vandalising a public noticeboard","option_d":"preventing others from joining a meeting","correct_answer":"B","explanation":"Volunteering contributes time or skill to a public or community need.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Taxation","question":"Why do governments collect taxes under the law?","option_a":"to fund public services and approved spending","option_b":"to give every official private property","option_c":"to replace all voluntary work","option_d":"to prevent citizens from asking questions","correct_answer":"A","explanation":"Tax revenue helps fund public services and government responsibilities.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Public finance","question":"A budget is primarily a plan of expected public ___.","option_a":"court judgments only","option_b":"income and expenditure","option_c":"family histories","option_d":"election results","correct_answer":"B","explanation":"A budget estimates revenue and sets out planned expenditure for a period.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Media literacy","question":"Before sharing a dramatic claim about an election, a responsible citizen should ___.","option_a":"forward it immediately","option_b":"alter the image to attract attention","option_c":"check reliable sources and verify the date and context","option_d":"remove all source information","correct_answer":"C","explanation":"Verification reduces the spread of false or misleading information.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Media literacy","question":"A photograph from an old flood is reposted as if it happened today. What is the main problem?","option_a":"it has too many colours","option_b":"it contains a date","option_c":"it was shared by a pupil","option_d":"the context is misleading","correct_answer":"D","explanation":"An old image presented as current misrepresents when the event occurred.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Cultural heritage","question":"An oral history interview is best preserved by ___.","option_a":"recording it with informed consent and noting its source","option_b":"changing the speaker’s words without notice","option_c":"deleting the speaker’s community name","option_d":"selling the recording without permission","correct_answer":"A","explanation":"Consent, accurate recording and source information help preserve heritage responsibly.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Cultural heritage","question":"A traditional festival is part of a community’s ___.","option_a":"court procedure","option_b":"cultural heritage","option_c":"tax code","option_d":"electoral register","correct_answer":"B","explanation":"A festival can express practices and knowledge passed through a community.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"History and sources","question":"A dated diary written by an eyewitness is generally a ___.","option_a":"fictional account","option_b":"secondary source only","option_c":"primary historical source","option_d":"census return","correct_answer":"C","explanation":"An eyewitness diary created at the time is a primary source.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Historical evidence","question":"Why should a historian compare more than one source about an event?","option_a":"to make every account identical","option_b":"to remove all disagreement","option_c":"to avoid checking dates","option_d":"to assess evidence and identify different perspectives","correct_answer":"D","explanation":"Comparing sources helps test claims and recognise perspective or bias.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Nigerian federation","question":"Which statement about Nigeria’s states and the Federal Capital Territory is correct?","option_a":"Nigeria has 36 states and a Federal Capital Territory","option_b":"Nigeria has 40 states and no capital territory","option_c":"Nigeria has 12 states and two capitals","option_d":"Nigeria has 774 states","correct_answer":"A","explanation":"Nigeria is made up of 36 states and the Federal Capital Territory.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Public institutions","question":"What is the main role of the National Assembly’s oversight function?","option_a":"to sentence every criminal directly","option_b":"to scrutinise executive agencies and public spending","option_c":"to appoint every traditional ruler","option_d":"to conduct school examinations","correct_answer":"B","explanation":"Legislative oversight checks executive implementation and use of public resources.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Checks and balances","question":"A legislature questions a minister about a government programme. This is an example of ___.","option_a":"cultural diffusion","option_b":"voter registration","option_c":"checks and balances","option_d":"judicial sentencing","correct_answer":"C","explanation":"Legislative scrutiny helps hold the executive accountable.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Political parties","question":"In a democracy, a political party mainly seeks to ___.","option_a":"replace the constitution privately","option_b":"prevent all opposition","option_c":"control the courts directly","option_d":"organise people to contest elections and promote policies","correct_answer":"D","explanation":"Political parties organise candidates and policy programmes to seek public office.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Elections","question":"What is the purpose of voter registration?","option_a":"to establish eligible voters for an election","option_b":"to guarantee a particular candidate wins","option_c":"to publish each person’s ballot choice","option_d":"to replace the constitution","correct_answer":"A","explanation":"Registration helps electoral authorities identify eligible voters.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"National values","question":"Which behaviour demonstrates integrity in a school election?","option_a":"changing a result to favour a friend","option_b":"counting votes honestly and reporting the result accurately","option_c":"destroying unused ballot papers","option_d":"hiding the election rules","correct_answer":"B","explanation":"Integrity means acting honestly and faithfully even when there is pressure to cheat.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"National values","question":"Showing respect for people with different beliefs is an example of ___.","option_a":"nepotism","option_b":"intolerance","option_c":"tolerance","option_d":"censorship","correct_answer":"C","explanation":"Tolerance involves respecting difference while living peacefully with others.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"National values","question":"A learner returns a wallet found in the school hall. Which value is shown?","option_a":"favouritism","option_b":"apathy","option_c":"intimidation","option_d":"honesty","correct_answer":"D","explanation":"Returning property that is not yours demonstrates honesty.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Public health","question":"During a community health campaign, reliable information should be obtained from ___.","option_a":"anonymous rumour pages","option_b":"qualified health authorities and professionals","option_c":"unverified forwarded messages","option_d":"advertisements that promise instant cures","correct_answer":"B","explanation":"Qualified public health sources are more reliable for health guidance.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":null,"subject":"Citizenship and Heritage Studies","topic":"Disaster preparedness","question":"A community flood plan should identify safe routes and ___.","option_a":"the most expensive houses","option_b":"political party slogans","option_c":"where residents can get alerts and assistance","option_d":"ways to block emergency workers","correct_answer":"C","explanation":"Preparedness includes warning systems, safe routes and support locations.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Cell structure","question":"Which organelle modifies and packages proteins for transport within a cell?","option_a":"ribosome","option_b":"Golgi apparatus","option_c":"centriole","option_d":"cell wall","correct_answer":"B","explanation":"The Golgi apparatus modifies, sorts and packages proteins and other molecules.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Cell structure","question":"Which structure is present in a typical plant cell but absent from an animal cell?","option_a":"mitochondrion","option_b":"cell membrane","option_c":"chloroplast","option_d":"cytoplasm","correct_answer":"C","explanation":"Chloroplasts carry out photosynthesis and are present in photosynthetic plant cells.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Cell structure","question":"What is the main function of the nucleus?","option_a":"to digest all food outside the cell","option_b":"to make cellulose cell walls","option_c":"to store cell sap only","option_d":"to contain genetic material and control cell activities","correct_answer":"D","explanation":"The nucleus contains DNA and regulates many activities of the cell.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Microscopy","question":"A microscope has a 10× eyepiece and a 40× objective lens. What is the total magnification?","option_a":"400×","option_b":"50×","option_c":"30×","option_d":"4×","correct_answer":"A","explanation":"Total magnification is eyepiece magnification multiplied by objective magnification: 10×40=400.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Microscopy","question":"Why should a student begin focusing a microscope with the low-power objective?","option_a":"it gives the greatest magnification","option_b":"it provides a wider field and lowers the risk of striking the slide","option_c":"it makes the specimen disappear","option_d":"it removes the need for light","correct_answer":"B","explanation":"Low power gives a wider field of view and makes initial focusing safer.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Cell transport","question":"The movement of water molecules through a selectively permeable membrane is called ___.","option_a":"diffusion","option_b":"active transport","option_c":"osmosis","option_d":"transpiration","correct_answer":"C","explanation":"Osmosis is the net movement of water through a selectively permeable membrane.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Cell transport","question":"A root hair absorbs mineral ions against a concentration gradient. Which process is required?","option_a":"simple diffusion","option_b":"osmosis","option_c":"transpiration","option_d":"active transport","correct_answer":"D","explanation":"Active transport uses energy to move substances against a concentration gradient.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Nutrition in plants","question":"Which gas is released during photosynthesis in green plants?","option_a":"oxygen","option_b":"nitrogen","option_c":"carbon dioxide","option_d":"hydrogen","correct_answer":"A","explanation":"Oxygen is released when water molecules are split during photosynthesis.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Nutrition in plants","question":"Which pigment absorbs light energy for photosynthesis?","option_a":"haemoglobin","option_b":"chlorophyll","option_c":"melanin","option_d":"keratin","correct_answer":"B","explanation":"Chlorophyll absorbs light energy in chloroplasts.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Nutrition in plants","question":"A destarched leaf is partly covered before exposure to sunlight. After testing for starch, the illuminated part turns blue-black. What does this show?","option_a":"water alone makes starch","option_b":"oxygen is stored as starch","option_c":"light is needed for starch formation in photosynthesis","option_d":"the covered part absorbed more light","correct_answer":"C","explanation":"The exposed part formed starch, showing that light was required under the test conditions.","difficulty":"hard","marks":2,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Nutrition in plants","question":"Which mineral element is needed to form chlorophyll molecules?","option_a":"sodium","option_b":"iodine","option_c":"chlorine","option_d":"magnesium","correct_answer":"D","explanation":"Magnesium is part of the chlorophyll molecule.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Nutrition in animals","question":"Which nutrient is the body’s main source of energy for ordinary activity?","option_a":"carbohydrate","option_b":"vitamin C","option_c":"water","option_d":"mineral salts","correct_answer":"A","explanation":"Carbohydrates are an important energy source and are broken down in respiration.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Nutrition in animals","question":"Which food test turns blue-black when starch is present?","option_a":"Biuret test","option_b":"iodine test","option_c":"ethanol emulsion test","option_d":"Benedict’s test","correct_answer":"B","explanation":"Iodine solution changes from brown to blue-black in the presence of starch.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Nutrition in animals","question":"A positive Biuret test for protein produces which colour?","option_a":"green","option_b":"brick-red","option_c":"violet or lilac","option_d":"blue-black","correct_answer":"C","explanation":"In alkaline solution, the Biuret reagent turns violet or lilac when protein is present.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Digestion","question":"Where does most absorption of digested nutrients occur in humans?","option_a":"stomach","option_b":"oesophagus","option_c":"large intestine","option_d":"small intestine","correct_answer":"D","explanation":"Villi in the small intestine provide a large surface area for nutrient absorption.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Digestion","question":"Which enzyme in saliva begins the digestion of starch?","option_a":"salivary amylase","option_b":"pepsin","option_c":"lipase","option_d":"trypsin","correct_answer":"A","explanation":"Salivary amylase starts breaking starch into smaller sugars in the mouth.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Digestion","question":"What is the main role of bile in fat digestion?","option_a":"it chemically digests protein","option_b":"it emulsifies fat into small droplets","option_c":"it converts glucose to starch","option_d":"it absorbs amino acids","correct_answer":"B","explanation":"Bile emulsifies large fat globules, increasing surface area for lipase.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Respiration","question":"Which equation best summarises aerobic respiration?","option_a":"glucose → starch + oxygen","option_b":"oxygen + water → glucose","option_c":"glucose + oxygen → carbon dioxide + water + energy","option_d":"carbon dioxide → glucose + nitrogen","correct_answer":"C","explanation":"Aerobic respiration releases energy as glucose reacts with oxygen to form carbon dioxide and water.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Respiration","question":"During vigorous exercise, muscle cells may produce which substance when oxygen is insufficient?","option_a":"ethanol","option_b":"starch","option_c":"urea only","option_d":"lactic acid","correct_answer":"D","explanation":"Anaerobic respiration in human muscles produces lactic acid and releases less energy.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Transport in humans","question":"Which blood component carries most oxygen from the lungs?","option_a":"red blood cells","option_b":"platelets","option_c":"plasma proteins only","option_d":"lymphocytes","correct_answer":"A","explanation":"Haemoglobin in red blood cells binds and transports most oxygen.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Transport in humans","question":"Which blood vessel carries blood away from the heart?","option_a":"vein","option_b":"artery","option_c":"capillary","option_d":"venule only","correct_answer":"B","explanation":"Arteries carry blood away from the heart, though the oxygen level depends on the circuit.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Transport in humans","question":"Which vessel is best adapted for exchange of gases and dissolved materials with tissues?","option_a":"artery","option_b":"vein","option_c":"capillary","option_d":"aorta only","correct_answer":"C","explanation":"Capillaries have thin walls and a large network that permits exchange with tissues.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Transport in humans","question":"Which blood component is chiefly involved in clot formation?","option_a":"red blood cells","option_b":"plasma water","option_c":"antibodies only","option_d":"platelets","correct_answer":"D","explanation":"Platelets help initiate blood clotting at a damaged vessel.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Excretion","question":"Which organ removes urea from the blood and forms urine?","option_a":"kidney","option_b":"lung","option_c":"pancreas","option_d":"stomach","correct_answer":"A","explanation":"The kidneys filter blood and excrete urea and excess water as urine.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Excretion","question":"Which waste product is removed from the body by the lungs?","option_a":"urea","option_b":"carbon dioxide","option_c":"bile pigment","option_d":"undigested fibre","correct_answer":"B","explanation":"Carbon dioxide produced in respiration diffuses into the lungs and is exhaled.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Homeostasis","question":"Sweating helps cool the body mainly because ___.","option_a":"sweat blocks all skin pores","option_b":"sweat increases body temperature","option_c":"evaporation of sweat removes heat from the skin","option_d":"sweat produces oxygen","correct_answer":"C","explanation":"Evaporation requires heat energy, which is taken from the skin and cools it.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Support and movement","question":"Which tissue connects a muscle to a bone?","option_a":"ligament","option_b":"cartilage","option_c":"epithelium","option_d":"tendon","correct_answer":"D","explanation":"A tendon attaches muscle to bone and transmits pulling force.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Support and movement","question":"Which structure joins one bone to another at a movable joint?","option_a":"ligament","option_b":"tendon","option_c":"nerve","option_d":"alveolus","correct_answer":"A","explanation":"Ligaments connect bones and help stabilise a joint.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Reproduction in plants","question":"After fertilisation in a flowering plant, which structure develops into the seed?","option_a":"petal","option_b":"ovule","option_c":"anther","option_d":"stigma","correct_answer":"B","explanation":"The fertilised ovule develops into a seed.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Reproduction in plants","question":"Which part of a flower receives pollen grains?","option_a":"filament","option_b":"ovary","option_c":"stigma","option_d":"sepal","correct_answer":"C","explanation":"The stigma is the receptive surface on which pollen lands.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Reproduction in plants","question":"Pollination is the transfer of pollen from the anther to the ___.","option_a":"ovary","option_b":"ovule","option_c":"petal","option_d":"stigma","correct_answer":"D","explanation":"Pollination transfers pollen from anther to stigma.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Reproduction in plants","question":"Which feature commonly helps wind-pollinated flowers release pollen?","option_a":"exposed anthers","option_b":"large coloured petals","option_c":"nectar glands","option_d":"heavy sticky pollen only","correct_answer":"A","explanation":"Exposed anthers allow wind to carry pollen away from the flower.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Reproduction in humans","question":"Where does fertilisation usually occur in the human female reproductive system?","option_a":"uterus","option_b":"oviduct","option_c":"vagina","option_d":"cervix","correct_answer":"B","explanation":"Fertilisation usually occurs in the oviduct, also called the fallopian tube.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Reproduction in humans","question":"Which organ produces sperm cells?","option_a":"prostate gland","option_b":"urinary bladder","option_c":"testis","option_d":"ureter","correct_answer":"C","explanation":"The testes produce sperm cells and the hormone testosterone.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Reproduction in humans","question":"Which organ supports development of the embryo during pregnancy?","option_a":"ovary","option_b":"oviduct","option_c":"cervix only","option_d":"uterus","correct_answer":"D","explanation":"The embryo implants and develops in the uterus.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Growth and development","question":"A permanent increase in the dry mass and size of an organism is called ___.","option_a":"growth","option_b":"movement","option_c":"irritability","option_d":"excretion","correct_answer":"A","explanation":"Biological growth involves a permanent increase in size and dry mass.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Classification","question":"Which feature is commonly used to classify flowering plants as monocots or dicots?","option_a":"number of legs","option_b":"number of cotyledons in the seed","option_c":"presence of a backbone","option_d":"type of blood cell","correct_answer":"B","explanation":"Monocots have one cotyledon, while dicots typically have two.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Classification","question":"Which kingdom includes organisms such as mushrooms that absorb nutrients from organic matter?","option_a":"Plantae","option_b":"Animalia","option_c":"Fungi","option_d":"Protista only","correct_answer":"C","explanation":"Mushrooms are fungi and obtain nutrients by absorption.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Ecology","question":"Green plants are called producers because they ___.","option_a":"feed on all consumers","option_b":"break down rocks into minerals","option_c":"hunt other organisms","option_d":"make organic food using light energy","correct_answer":"D","explanation":"Producers such as green plants form organic food through photosynthesis.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Ecology","question":"In the food chain grass → grasshopper → frog, which organism is the primary consumer?","option_a":"grasshopper","option_b":"grass","option_c":"frog","option_d":"decomposer","correct_answer":"A","explanation":"The grasshopper feeds directly on the producer grass.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Ecology","question":"What is the main role of decomposers in an ecosystem?","option_a":"remove sunlight","option_b":"break down dead matter and recycle nutrients","option_c":"produce all rainfall","option_d":"stop energy entering the food chain","correct_answer":"B","explanation":"Decomposers return nutrients from dead organisms and waste to the environment.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Ecology","question":"A group of organisms of the same species living in one area is a ___.","option_a":"community","option_b":"ecosystem","option_c":"population","option_d":"habitat","correct_answer":"C","explanation":"A population consists of members of the same species in a particular area.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Ecology","question":"Which is a biotic factor affecting organisms in a pond?","option_a":"water temperature","option_b":"light intensity","option_c":"soil mineral content","option_d":"predation by fish","correct_answer":"D","explanation":"Predation is an interaction among living organisms and is biotic.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Ecology","question":"Which is an abiotic factor that can affect crop growth?","option_a":"soil pH","option_b":"competition among weeds","option_c":"grazing by goats","option_d":"fungal infection","correct_answer":"A","explanation":"Soil pH is a non-living chemical condition and therefore abiotic.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Adaptation","question":"Broad, waxy leaves in some plants help reduce water loss mainly by ___.","option_a":"increasing transpiration","option_b":"limiting evaporation from the leaf surface","option_c":"preventing photosynthesis","option_d":"absorbing oxygen from soil","correct_answer":"B","explanation":"A waxy cuticle reduces evaporation from the leaf surface.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Health and disease","question":"Malaria is transmitted to humans by the bite of an infected ___.","option_a":"housefly","option_b":"tsetse fly","option_c":"female Anopheles mosquito","option_d":"cockroach","correct_answer":"C","explanation":"An infected female Anopheles mosquito transmits the malaria parasite.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Health and disease","question":"Which measure helps prevent the spread of cholera?","option_a":"sharing untreated water","option_b":"leaving food uncovered","option_c":"using a stream as a toilet","option_d":"safe water, sanitation and handwashing","correct_answer":"D","explanation":"Clean water, sanitation and good hygiene interrupt faecal-oral transmission.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Health and disease","question":"Vaccination protects a person primarily by ___.","option_a":"stimulating immune memory against a pathogen","option_b":"removing all microbes from the environment","option_c":"replacing red blood cells","option_d":"stopping the heart rate from changing","correct_answer":"A","explanation":"Vaccines train the immune system to recognise a pathogen and respond more effectively.","difficulty":"medium","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Variation","question":"A difference in eye colour among members of a human population is an example of ___.","option_a":"photosynthesis","option_b":"variation","option_c":"respiration","option_d":"excretion","correct_answer":"B","explanation":"Variation describes differences among individuals of the same species.","difficulty":"easy","marks":1,"is_active":true},{"level":"SS1","category":"science","subject":"Biology","topic":"Inheritance","question":"Which molecule carries hereditary information in most living organisms?","option_a":"starch","option_b":"cellulose","option_c":"DNA","option_d":"glycogen","correct_answer":"C","explanation":"DNA stores genetic information that can be passed from parents to offspring.","difficulty":"easy","marks":1,"is_active":true}]$seed$::jsonb;
  v_count integer;
  v_inserted integer;
  v_skipped integer;
  v_duplicate record;
begin
  v_count := jsonb_array_length(v_rows);
  if v_count <> 250 then
    raise exception 'Expected 250 questions in this batch, found %', v_count;
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_rows) as b(
      level text, category text, subject text, topic text, question text,
      option_a text, option_b text, option_c text, option_d text,
      correct_answer text, explanation text, difficulty text, marks numeric, is_active boolean
    )
    where level <> 'SS1'
       or subject not in ('English Language','General Mathematics','Digital Technologies','Citizenship and Heritage Studies','Biology')
       or (subject in ('English Language','General Mathematics','Digital Technologies','Citizenship and Heritage Studies') and category is not null)
       or (subject = 'Biology' and category is distinct from 'science')
       or correct_answer not in ('A','B','C','D')
       or difficulty not in ('easy','medium','hard')
       or marks <= 0
       or is_active is distinct from true
       or btrim(question) = ''
       or btrim(topic) = ''
       or btrim(explanation) = ''
       or num_nonnulls(option_a,option_b,option_c,option_d) <> 4
       or (select count(distinct lower(btrim(opt)))
           from unnest(array[option_a,option_b,option_c,option_d]) as choices(opt)) <> 4
  ) then
    raise exception 'Batch has invalid question fields, category, answer key, or options';
  end if;

  if (select count(distinct subject)
      from jsonb_to_recordset(v_rows) as b(
        level text, category text, subject text, topic text, question text,
        option_a text, option_b text, option_c text, option_d text,
        correct_answer text, explanation text, difficulty text, marks numeric, is_active boolean
      )) <> 5
     or exists (
       select 1 from jsonb_to_recordset(v_rows) as b(
         level text, category text, subject text, topic text, question text,
         option_a text, option_b text, option_c text, option_d text,
         correct_answer text, explanation text, difficulty text, marks numeric, is_active boolean
       ) group by subject having count(*) <> 50
     ) then
    raise exception 'Each of the five subjects must contain exactly 50 questions';
  end if;

  if exists (
    select 1 from jsonb_to_recordset(v_rows) as b(
      level text, category text, subject text, topic text, question text,
      option_a text, option_b text, option_c text, option_d text,
      correct_answer text, explanation text, difficulty text, marks numeric, is_active boolean
    )
    group by lower(btrim(subject)), lower(btrim(question)) having count(*) > 1
  ) then
    raise exception 'Duplicate question wording exists within the batch';
  end if;

  for v_duplicate in
    select distinct b.subject, b.question
    from jsonb_to_recordset(v_rows) as b(
      level text, category text, subject text, topic text, question text,
      option_a text, option_b text, option_c text, option_d text,
      correct_answer text, explanation text, difficulty text, marks numeric, is_active boolean
    )
    join public.question_bank q
      on q.level = b.level
     and lower(btrim(q.subject)) = lower(btrim(b.subject))
     and lower(btrim(q.question)) = lower(btrim(b.question))
    order by b.subject, b.question
  loop
    raise notice 'Skipping exact question already in public.question_bank (subject=%): %',
      v_duplicate.subject, v_duplicate.question;
  end loop;

  insert into public.question_bank (
    level, category, subject, topic, question, option_a, option_b, option_c,
    option_d, correct_answer, explanation, difficulty, marks, is_active
  )
  select level, category, subject, topic, question, option_a, option_b, option_c,
         option_d, correct_answer, explanation, difficulty, marks, is_active
  from jsonb_to_recordset(v_rows) as b(
    level text, category text, subject text, topic text, question text,
    option_a text, option_b text, option_c text, option_d text,
    correct_answer text, explanation text, difficulty text, marks numeric, is_active boolean
  )
  where not exists (
    select 1
    from public.question_bank q
    where q.level = b.level
      and lower(btrim(q.subject)) = lower(btrim(b.subject))
      and lower(btrim(q.question)) = lower(btrim(b.question))
  )
  on conflict (level, (lower(btrim(subject))), (lower(btrim(question)))) do nothing;
  get diagnostics v_inserted = row_count;
  v_skipped := v_count - v_inserted;
  raise notice 'Batch 002 inserted % new questions and skipped % exact duplicates.',
    v_inserted, v_skipped;
end $$;

commit;
